class Widget {
  constructor(public name: string, public config: any) {}
  clone(): Widget {
    return Object.assign(Object.create(Object.getPrototypeOf(this)), this);
  }
}
const base = new Widget('button', { color: 'blue', size: 'md' });
const copy = base.clone();
copy.config.color = 'red';

class Order {
  constructor(public id: number, public items: string[]) {}
  clone(): Order {
    // shallow copy via Object.assign
    return Object.assign(Object.create(Object.getPrototypeOf(this)), this);
  }
}
const o1 = new Order(1, ['apple']);
const o2 = o1.clone();
o2.items.push('banana');

// Version A: registry of configured instances and clone method
class EmailTemplate {
  constructor(public subject: string, public body: string, public attachments: string[] = []) {}
  clone(): EmailTemplate { return new EmailTemplate(this.subject, this.body, this.attachments.slice()); }
}
const registry = new Map<string, EmailTemplate>();
registry.set('welcome', new EmailTemplate('Welcome', 'Hello!', ['logo.png']));
const instanceA = registry.get('welcome')!.clone();

// Version B: factory that requires rebuilding configuration for each creation
function createEmailTemplate(cfg: { subject: string; body: string; attachments?: string[] }) {
  return new EmailTemplate(cfg.subject, cfg.body, cfg.attachments || []);
}
const base = { subject: 'Welcome', body: 'Hello!', attachments: ['logo.png'] };
const instanceB = createEmailTemplate({ ...base });
